import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import { drizzle } from "drizzle-orm/node-postgres";
import { migrate } from "drizzle-orm/node-postgres/migrator";
import pg from "pg";

/**
 * Migrations generated by drizzle-kit; resolves from both `src/` and `dist/`. Built with
 * `path.join` rather than `new URL("../drizzle", import.meta.url)`, which bundlers
 * (Turbopack) try to resolve as an asset import.
 */
export const migrationsFolder = join(dirname(fileURLToPath(import.meta.url)), "..", "drizzle");

/** Applies all pending migrations (including the review profile seed) to `connectionString`. */
export async function runMigrations(connectionString: string): Promise<void> {
  const client = new pg.Client({ connectionString });
  await client.connect();
  try {
    await migrate(drizzle(client), { migrationsFolder });
  } finally {
    await client.end();
  }
}
